def check_prime_power(e):
    """Checks if 3e + 1 is a power of an odd prime p, for e >= 1."""
    target = 3 * e + 1
    if target <= 1:
        return None

    # Check for factorization
    factors = {}
    d = 2
    temp = target
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    # Check if it is a prime power p^e
    if len(factors) == 1:
        p = list(factors.keys())[0]
        exp = factors[p]
        # We are looking for 3e + 1 = p^e, so the exponent must be e.
        if p % 2 != 0 and exp == e:
            return p
    return None

